mapper.select:
SELECT dm.dept_code, dm.company_code, dm.dept_name, dm.upper_dept_no,
dmu.dept_name as upper_dept_name,
dm.dept_level, dm.start_date, dm.end_date,
ccs.code_name as status,
dm.rm FROM tb_dept_master dm
JOIN tb_cm_code ccs ON ccs.group_code = '0R'
LEFT JOIN tb_dept_master dmu ON dmu.dept_code = dm.upper_dept_no
WHERE 1=1 AND dm.company_code = #{companyCode} AND ccs.code = dm.status
AND dm.dept_code = #{deptName}
AND dmu.dept_code = #{upperDeptName}
AND ccs.code = #{status}
AND dm.dept_level >= #{deptCodeManageStartLevel}
AND dm.dept_level <= #{deptCodeManageEndLevel}
